// Map languages that have sub-locales (e.g. pa-IN -> pa)
export const getTranslationsForLang = (langCode: string): Record<string, { title: string; message: string }> => {
  const short = langCode.split('-')[0].toLowerCase();
  
  if (short === 'pa') return ALERT_TRANSLATIONS['pa'];
  if (short === 'mr') return ALERT_TRANSLATIONS['mr'];
  if (short === 'bn') return ALERT_TRANSLATIONS['bn'];
  if (short === 'ta') return ALERT_TRANSLATIONS['ta'];
  if (short === 'te') return ALERT_TRANSLATIONS['te'];
  if (short === 'kn') return ALERT_TRANSLATIONS['kn'];
  if (short === 'ml') return ALERT_TRANSLATIONS['ml'];
  if (short === 'gu') return ALERT_TRANSLATIONS['gu'];
  if (short === 'hi') return ALERT_TRANSLATIONS['hi'];
  if (short === 'as') return ALERT_TRANSLATIONS['as'];
  if (short === 'or' || short === 'od') return ALERT_TRANSLATIONS['or'];
  
  return ALERT_TRANSLATIONS[short] || ALERT_TRANSLATIONS['en'];
};
